-- Atributos técnicos de referência por categoria (dados de catálogo, não demo).
-- Idempotente. Rollback: DELETE FROM `material_attributes` WHERE `id` LIKE '00000000-0000-4000-8100-%';

ON DUPLICATE KEY UPDATE
  `label` = VALUES(`label`),
  `type` = VALUES(`type`),
  `unit` = VALUES(`unit`),
  `options` = VALUES(`options`),
  `sort_order` = VALUES(`sort_order`);
